arg={} ; package.path='./src/?.lua;./src/?/init.lua;'..package.path; local Prom=require('prometheus'); local preset={LuaVersion='Lua51',PrettyPrint=true,Steps={{Name='Vmify'},{Name='ConstantArray',Settings={Treshold=1,StringsOnly=true,Shuffle=true,Rotate=true,LocalWrapperTreshold=0}}}}; local p=Prom.Pipeline:fromConfig(preset); local src=io.open('tests.lua','r'):read('*a'); local out=p:apply(src,'tests'); local i=1; for line in out:gmatch('[^\n]*\n') do if i>=240 and i<=280 then print(string.format('%3d: %s',i,line)); end i=i+1; end